import sys

def move_left(a):
    res = []
    pending = 0
    for x in a:
        if x == 0:
            continue
        if pending == x:
            res.append(2 * x)
            pending = 0
        else:
            if pending:
                res.append(pending)
            pending = x
    if pending:
        res.append(pending)
    return res + [0] * (len(a) - len(res))

data = sys.stdin.read().split()
n = int(data[0])
d = data[1]
a = [int(x) for x in data[2:2 + n]]
if d == 'left':
    r = move_left(a)
else:
    r = move_left(a[::-1])[::-1]
print(' '.join(map(str, r)))

