    for b in base:
        for d in ('left', 'right'):
            tests.append(fmt(b, d))
    vals = [0, 0, 1, 2, 2, 4, 4, 8]
    for n in (3, 5, 8, 12, 20, 30):
        for _ in range(3):
            tests.append(fmt([rng.choice(vals) for _ in range(n)], rng.choice(['left', 'right'])))
    n = 10**5
    tests.append(fmt([rng.choice([0, 2, 4, 8]) for _ in range(n)], 'left'))
    tests.append(fmt([rng.choice([0, 2, 4, 8]) for _ in range(n)], 'right'))
    tests.append(fmt([2 ** rng.randint(0, 20) if rng.random() < 0.7 else 0 for _ in range(n)], 'left'))
    tests.append(fmt([1048576] * n, 'right'))
    return tests

